const e="La forêt n'est pas leur royaume. Elle est leur foyer.",t="Adage Lythari",n=["Peuple & Lignée","Elfes des Forêts","Codex #PEU-006"],r=[6,7,8],s="Trésabia, Forêts du Vieux Monde",a="Agilité, Connexion à Quaara, Discrétion",i="165cm - 190cm",o="300",l="« Peuple des feuilles portées par le vent »",c="Lythari_icone.jpeg",u="Commun",d=[{title:"Présentation",type:"text",content:"Les Lythari sont les Elfes des forêts vivant principalement dans le royaume forestier de Trésabia. Leur civilisation est pensée pour s'adapter à l'environnement naturel sans le dénaturer."},{title:"La Guerre des Forêts",type:"text",content:"Les Lythari maîtrisent des tactiques de harcèlement et de guérilla uniques, rendant les frontières de Trésabia quasi infranchissables pour les armées étrangères."},{title:"Relations avec les autres peuples",type:"politique_list_long",content:[{headline:"Fraternelle",title:"Les Virelith",content:"Partagent une origine commune et protègent conjointement les frontières naturelles de Trésabia.",color:"#34D399"},{headline:"Neutre / Prudent",title:"Les Valm & Kovraks",content:"Refusent de prendre parti dans le conflit entre Lorus et Koven pour protéger leurs forêts.",color:"#C29B38"},{headline:"Amical",title:"Les Vhaerith",content:"Furent parmi les premiers à chercher à comprendre la condition des Vhaerith.",color:"#34D399"}]},{title:"Aujourd'hui",type:"text",content:"Concentrés à Trésabia, ils demeurent les gardiens vigilants de la nature et participent activement à l'étude des anomalies d'Asun."}],p={citation:e,citation_author:t,tags:n,link_articles:r,class:"Elfique",repart:s,trait:a,height:i,age:o,surname:l,image:c,statut:u,sections:d};export{o as age,e as citation,t as citation_author,p as default,i as height,c as image,r as link_articles,s as repart,d as sections,u as statut,l as surname,n as tags,a as trait};
